    bag_examples_v2_toast: "🎁 Nowe przykłady w Twojej torbie: pomysły na prezent, lista do hotelu i lista na lot ✨",
    faq_a_bag_examples_list: "Nowa torba ma przykłady, które możesz zmienić lub usunąć jak wszystko inne: Dom (zakupy, przepisy, posiłki na ten tydzień), Rodzina (małe chwile, lista na przyjęcie urodzinowe, zajęcia i aktywności), Pomysły (pomysły na weekend, pomysły na prezent według kategorii, i co zrobić z zaoszczędzonymi pieniędzmi) i Wyjazdy (miejsca, do których chcesz pojechać, lista rzeczy na wyjazd, rzeczy do hotelu i lista na lot za granicę). Torba, która już istniała, dostaje jednorazowo najnowsze – do własnych kieszeni.",
    faq_q_bag_examples_list: "Jakie przykłady są w Mojej torbie?",
    faq_a_nm_me1_guide: "Sky – twoja postać w New Me, w swojej pierwszej formie (Sky 1). Za pierwszym razem, tuż po dołączeniu, otwiera się portal światła otoczony iskierkami i wylatuje z niego Sky, w kilku dotknięciach wyjaśnia, co cię czeka, a potem zostaje przy każdym pytaniu: podczas wybierania posiłków pisze razem z tobą w swojej księdze, a dotknięcie jego wskazówki pokazuje kolejną. Na koniec Sky świętuje z tobą i zabiera cię na krótką wycieczkę – a gdy wycieczka się kończy, ma dla ciebie jeszcze jedną małą chwilę. Jeśli wyjdziesz w połowie – pytań albo wycieczki – następnym razem Sky cieszy się na twój widok i pyta, czy kontynuować od tego samego miejsca.",
