    room_genie_again_no_msg: "W takim razie czas osiągać cele, które już są wyznaczone. Kiedy dotrzesz do następnego – coś będzie tam na ciebie czekać ✨",
    room_genie_again_q: "Znowu tutaj? ✨ Chcesz zmienić w swoim życiu coś jeszcze?",
    room_genie_again_yes: "Tak",
    room_genie_bye: "Do zobaczenia",
