    faq_a_shop_holidays: "Na Liście Zakupów dotknij prezentu: po kolei pojawią się święta twojego kraju (tego wybranego w Ustawieniach) z datami, które co roku obliczają się same. Dotknij święta, by zobaczyć gotową listę tego, co się na nie kupuje; wszystko jest zaznaczone (oprócz tego, co już jest na twojej liście), odznacz to, czego nie potrzebujesz, i dotknij „Dodaj do listy”. Dwa tygodnie przed świętem na górze listy pojawia się mała karta; ✕ ukrywa ją do następnego święta.",
    faq_q_shop_holidays: "Jak działa „Co kupić na święto”?",
    shop_hol_add: "Dodaj do listy ({n})",
    shop_hol_added: "Dodano do listy: {n}",
    shop_hol_btn: "Co kupić na święto",
    shop_hol_items_title: "{holiday} – co kupić?",
    shop_hol_not_now: "Nie teraz",
    faq_a_shop_delivery: "Na Liście Zakupów dotknij ciężarówki: wybierz, co jest w dostawie (wszystko jest zaznaczone), kiedy dotrze – dziś, jutro czy innego dnia – i o jakiej porze (rano, popołudnie, wieczór albo „Inne…”, by wpisać własne godziny). Te produkty przechodzą na kartę „W drodze” na górze listy, z dniem i godzinami. Gdy nadejdzie ten dzień, w Moim Dniu pojawi się „Czy dostawa dotarła?” (a na karcie – „Dotarła?”). Jeśli wszystko dotarło, trafiają do „Kup ponownie”. Jeśli czegoś brakuje, dotknij tego, co nie dotarło, a wróci prosto na listę.",
    faq_a_shop_departments: "Lista sama układa się według działów w supermarkecie – owoce i warzywa, pieczywo, nabiał i jajka, mięso i ryby, spiżarnia, mrożonki, napoje, przekąski, chemia, higiena, dla dziecka i zwierzęta – dzięki temu przechodzisz alejki po kolei. Dział jest rozpoznawany po nazwie produktu. Jeśli produkt trafił w złe miejsce, dotknij go i wybierz jego dział albo „Inny…”, by wpisać własny.",
    faq_a_shop_share_qty: "Tak. Obok każdego produktu + dodaje jeden więcej (×2, ×3…), a − odejmuje jeden. Przycisk udostępniania na górze Listy Zakupów wysyła całą listę, starannie ułożoną według działów, przez WhatsApp, e-mailem lub jako kopię.",
    faq_a_shop_two_buttons: "Oba znaczą „kupione”. ✕ jest dla czegoś, co kupujesz raz – znika z listy (i czeka w archiwum 🗑️, gdyby to była pomyłka). ↺ jest dla rzeczy kupowanych wciąż na nowo – znikają z listy i czekają w „Kup ponownie”: to miejsce otwiera mały przycisk ↺ obok kosza na dole listy, a jedno dotknięcie tam przywraca produkt na listę. W „Edytuj” w środku możesz usunąć z niego produkt. Gdy dodajesz produkt, rzeczy kupione wcześniej pojawiają się jako podpowiedzi, a jeśli produkt już jest na liście, po prostu zmienia się w ×2 zamiast drugiej linii.",
    faq_q_shop_delivery: "Jak działa „Mam zamówioną dostawę”?",
