    nm_demo_saved_2: "Jogurt z granolą i owocami",
    nm_demo_title: "Jak działa zamiana",
    faq_a_new_me_challenge_journal: "Gdy wyzwanie się kończy – duże, mini czy wyzwanie tygodnia – w gratulacjach pojawia się przycisk 📝 Jak poszło?, który otwiera stronę w dzienniku wyzwań: jak było (pięć buziek), co pomogło, co było trudne i co zabrać ze sobą dalej – nic nie jest obowiązkowe i można to też zostawić na później. Dziennik to diament w magicznym plecaku: każde ukończone wyzwanie z datą i tym, co zostało zapisane, najnowsze na górze – dotknij jednego, żeby je przeczytać, edytować albo udostępnić (udostępnia się tylko to, co jest na stronie). Ukończone wyzwanie dostaje też medal w osiągnięciach, w sekcji „Ukończone wyzwania”. Dziennik wyzwań jest oddzielny od pamiętnika.",
    faq_q_new_me_challenge_journal: "Czym jest dziennik wyzwań?",
