    nm_chj_mood_5: "Świetnie",
    nm_chj_q: "Jak poszło wyzwanie?",
    nm_chj_reflect_btn: "Jak poszło?",
    nm_chj_save: "Zapisz w dzienniku wyzwań",
    nm_chj_saved: "Zapisano w dzienniku wyzwań",
    nm_chj_share_text: "Wyzwanie w New Me ukończone ✨",
    nm_chj_take: "Co zabrać ze sobą dalej?",
    nm_chj_title: "Dziennik wyzwań",
    nm_chj_write: "Opisz, jak poszło",
    nm_swap_time: "Godzina",
    faq_a_ai_reminder_in_text: "Tak – napisz je razem z zadaniem, na przykład „jutro o 17:00 odebrać paczkę, z przypomnieniem godzinę wcześniej”. Przypomnienie zapisuje się w samym zadaniu: godzinę wcześniej, pół godziny, dzień wcześniej i tak dalej, a „przypomnij mi” bez godziny oznacza 10 minut wcześniej. Przypomnienie wpisane w tekście ma pierwszeństwo przed polem przypomnienia w tym samym oknie.",
    faq_q_ai_reminder_in_text: "Czy mogę poprosić asystenta AI o przypomnienie w tej samej prośbie?",
    myday_meals_all_done: "Wszystkie dzisiejsze posiłki są odhaczone 🍽️",
    nm_tour_week_text: "Małe wyzwanie na tydzień. ✓ każdego dnia – a na końcu klucz.",
    books_home_chip: "{title} · s. {page}",
    books_home_of: "z {total}",
    books_home_off_toast: "Książka zniknęła z ekranu głównego",
    books_home_on_toast: "Książka jest na ekranie głównym 📖",
    books_home_pin: "Na ekranie głównym",
    books_home_q: "Na której jestem stronie?",
    books_home_save: "Zapisz",
    faq_a_books_home_chip: "Tak. W Kąciku czytelniczym, na karcie czytanej książki, dotknij 📌 Na ekranie głównym. Pod powitaniem na ekranie głównym pojawi się mały przycisk z książką i stroną – dotknij go, wpisz nowy numer strony i zapisz, a postęp zostanie zapisany (także w Kąciku czytelniczym). Ponowne dotknięcie 📌 zdejmuje go. Może tam być kilka książek naraz – każda z własnym przyciskiem – i wszystko wygląda tak samo na każdym urządzeniu.",
    faq_a_new_me_week_challenge: "Małe wyzwanie na jeden tydzień, wybrane przez Ciebie. W korytarzu jest duża karta: „Nad czym chcesz popracować w tym tygodniu?” – dotknij jej, wybierz obszar (ze sobą, z innymi, uczyć się i rozwijać, spokój, małe odważne kroki, dom i rutyna) i wyzwanie, a potem wybierz, kiedy ma się zacząć. Te same wyzwania są też na ekranie wyzwań, pod 🌱 Rozwój osobisty. Każdego dnia zaznaczaj ✓ na karcie (jeden wolny dzień w tygodniu), a każdy zakończony tydzień przynosi nowy klucz do tajnego świata. „Czytaj 2 strony dziennie” zaznacza się samo na podstawie stron zapisanych w Kąciku czytelniczym. Gdy tydzień się skończy, 📌 Zostaw jako codzienne zadanie dodaje je do Mojej Rutyny o wybranej godzinie, z ✓ każdego dnia. Naraz trwa jedno wyzwanie tygodnia; duże i mini wyzwania toczą się równolegle.",
    faq_a_room_genie: "Na werandzie z widokiem na morze dotknięcie lampy Aladyna wywołuje ducha lasu – i zaczyna się rozmowa: jakie jest życzenie (co chciałoby się zmienić w życiu), jakie to będzie uczucie, gdy się spełni, co jest trudne po drodze i jak można obrócić obecną sytuację w coś dobrego. Potem mniej więcej ile to potrwa, pierwszy mały krok i dwa kolejne oraz „jeśli… to…” na trudne chwile. Na końcu całe życzenie pojawia się krok po kroku i może stać się celem w Moich Celach (kroki zamieniają się w etapy na ścieżce, z datą zależną od wybranego czasu; tam wszystko można zmienić) albo zostać zapisane w pamiętniku – a wtedy duch się żegna. Nic nie jest zapisywane, jeśli nie wybierze się jednego z tych dwóch. Od drugiej wizyty duch najpierw pyta, czy chciałoby się zmienić w życiu coś jeszcze: tak – ta sama rozmowa; nie teraz – przypomnienie, by osiągać już wyznaczone cele. Duch wychodzi raz dziennie: po zapisaniu życzenia (albo po „Nie teraz”) odpoczywa do jutra. Pytania opierają się na znanym sposobie zamiany życzenia w plan: życzenie, rezultat, przeszkoda i plan.",
    faq_q_books_home_chip: "Czy mogę zobaczyć swoją książkę i stronę na ekranie głównym?",
    faq_q_new_me_week_challenge: "Czym jest wyzwanie tygodnia?",
    faq_q_room_genie: "Co robi dżin z lampy?",
