    room_drawer_aria: "Mała szafka",
    nm_me_choose: "Wybierz",
    nm_me_on_screen: "Na ekranie",
    faq_a_new_me_game: "W New Me przyciski gry zawsze zostają w tym samym miejscu – w korytarzu, w sekretnym pokoju i wszędzie w lesie; zmienia się tylko obraz pośrodku. Na górze: dzień podróży, klucze, seria i dzisiejsza energia (ile z planu już zjedzone), a pod spodem następna misja – następny posiłek o swojej porze (dotknięcie go otwiera, razem z ✓ Zjedzone). Z boku: cały dzień, wyzwania i moja podróż, a obok nich wyzwanie tygodnia – jego 7 dni i ✓ na dziś. Na dole: magiczny plecak (całe New Me – mapa świata, moja podróż, lista zakupów, osiągnięcia, dziennik wyzwań, pomiary, zdjęcia postępów, kalendarz miesiąca, tabela dzienna, przypomnienia, menu w PDF i ustawienia; otwiera się jako osobny ekran). Mapa świata, pierwsza rzecz w plecaku, pokazuje każde miejsce w lesie – dotknij miejsca, żeby tam przejść; przy zamkniętym miejscu widać, ilu kluczy potrzeba. Sky to twoja postać na ścieżce w lesie: zaczyna jako Sky 1, po kilku wyzwaniach (4 klucze) wyrasta na Sky 2, a pod koniec (9 kluczy) na Sky 3 – z metamorfozą, którą widać na własne oczy. Dotknij Skya, żeby zobaczyć wszystkie etapy – każdy już osiągnięty etap można wybrać ponownie, więc wcześniejszy może wrócić. Sky unosi się w powietrzu – przeciąga się go palcem lub myszą, a wejście, którego dotknie, się otwiera (przy zamkniętym widać, ilu kluczy brakuje). Sky idzie też z tobą do każdego pokoju i miejsca i unosi się tam, gdzie go zostawisz: przeciągnij go gdziekolwiek, a świecący pierścień pod nim przeciągnij, żeby obrócić go dookoła własnej osi; patrzy w stronę, w którą się porusza (na komputerze: strzałki go przesuwają, Q i E obracają). W korytarzu mała 🏠 pod górnym paskiem wraca do ekranu głównego; w każdym pokoju i miejscu przycisk w tym samym rogu wraca do korytarza.",
    faq_q_new_me_game: "Jak działają przyciski gry, mapa świata i Sky?",
