    room_magic_song_rec3: "Dzwonki wodospadu",
    faq_a_new_me_menu_build: "Najpierw ankieta pyta, jakie posiłki jesz i kiedy (2 posiłki + przekąska, 2 posiłki + lekka kolacja albo jedno i drugie) oraz czy wieczorem jest coś – do zjedzenia czy do picia, co i o której. Przy „2 posiłki + przekąska” posiłki to obiad (11:30) i kolacja (19:00), a przekąska o 16:00. Potem pojawiają się wszystkie propozycje dla tych posiłków. Wybierz do 2 ulubionych na każdy posiłek – w menu jest napisane „to albo tamto”. W niektórych propozycjach (pita i pasta, płatki z mlekiem, coś lekkiego) wybierasz do 3 rzeczy, które lubisz, każdą w jej własnej porcji, a w menu jest napisane „to albo tamto, albo tamto”; kalorie zależą od tego, co wybierzesz. Kawa i napoje działają tak samo. Każdy wybór jest zbilansowany, więc dzień sumuje się dokładnie do 1300 lub 1500. Aby zmienić to w dowolnej chwili: ⚙️ Ustawienia → 🍽️ Ułóż swoje menu albo „Wybierz do 3, które lubisz” na karcie posiłku.",
