    faq_a_myday_water_toggle: "Tak. Szklanka wody w Moim Dniu (z + na kolejną szklankę) jest domyślnie widoczna. Aby ją ukryć, wyłącz „Pokaż wodę w Moim Dniu” w Ustawienia > Personalizacja i kalendarz. Nic nie jest usuwane – Śledzenie Wody działa dalej, a po ponownym włączeniu szklanka wraca.",
    faq_q_myday_water_toggle: "Czy można ukryć wodę w Moim Dniu?",
    myday_water_toggle_label: "Pokaż wodę w Moim Dniu",
    faq_a_routine_newme_sync: "Z New Me w ⚙️ Mojej Rutyny jest przełącznik „Synchronizuj z New Me”. Gdy jest włączony (domyślnie), dzisiejsze posiłki New Me pojawiają się w Moim Dniu i w Mojej Rutynie – w miejscu ukrytych posiłków z rutyny. Gdy jest wyłączony, posiłki New Me znikają z obu miejsc, a rutyna wraca dokładnie do poprzedniego stanu. Nic nie jest usuwane – ponowne włączenie przywraca wszystko i pyta, które posiłki z rutyny ukryć.",
