    theme_name_watercolor_wash: "Akwarela",
    faq_a_food_list_languages: "Wbudowana lista produktów powstała z izraelskich potraw i ich hebrajskich nazw. We wszystkich pozostałych językach każdy produkt ma angielską nazwę, a wyszukiwarka znajduje każdą znaną jej angielską nazwę (na przykład 'broth' znajduje Clear soup); produkty, które mają tylko hebrajską nazwę, nie są tam pokazywane. Wszystko, czego nie ma na liście, można po prostu wpisać własnymi słowami – szacowanie przez AI działa w każdym języku.",
