    settings_copyright_line: "© 2026 wszelkie prawa zastrzeżone. opracowanie aplikacji: eden zabari.",
    workout_ready_replace_btn: "Zastąp",
    faq_a_sport_workout_ai: "W „Moje treningi” → ⋯ → „Plan z AI” (a gdy tabela jest pusta, także na kafelku obok gotowych planów). Odpowiedz kilkoma dotknięciami – ile razy w tygodniu, kiedy, miejsce, poziom i cel, prawie wszędzie jest też „Inne” – i jeśli chcesz, dodaj wolną linijkę, np. wrażliwe kolano albo bieg na 5 km do lata. AI układa cały tydzień: rodzaje treningów, dni, godziny, czas trwania, intensywność, ćwiczenia i dni odpoczynku. Zanim cokolwiek zostanie zapisane, pojawia się podgląd: „Wstaw do mojej tabeli” (zamiast tabeli albo jako dodatek), „Inna propozycja” (do 3 razy) lub „Zmień odpowiedzi”. Plan jest celowo umiarkowany, a jeśli wspomnisz o bólu lub kontuzji, dostaniesz łagodne opcje i radę, by skonsultować się ze specjalistą. Korzysta z tego samego limitu AI co harmonogram i rutyna: 5 razy za darmo i 60 razy w miesiącu z Premium.",
    faq_q_sport_workout_ai: "Jak utworzyć plan treningowy z AI?",
