    workout_ai_when_noon: "W południe",
    workout_ai_when_ph: "np. po pracy albo 17:30",
    workout_ai_working: "Plan się tworzy…",
    faq_a_sport_workout_jar: "Każdy rodzaj treningu ma własną kolorową gwiazdkę – bieganie różową, chodzenie zieloną, pływanie niebieską i tak dalej. Każdy trening zapisany w tym tygodniu, z tabeli lub osobno, wrzuca swoją gwiazdkę do słoika na górze „Moich treningów”, a słoik napełnia się aż do celu tygodniowego (dotknij go, aby zmienić cel). Po osiągnięciu celu słoik świeci. Mały słoik obok liczy, ile tygodni z rzędu był pełny.",
    faq_q_sport_workout_jar: "Czym są kolorowe gwiazdki i słoik w „Moich treningach”?",
    faq_a_sport_workout_gcal: "Tak – w ⋯ → Kalendarz Google (po połączeniu Kalendarza Google w Ustawieniach). Każdy trening z godziną staje się wydarzeniem powtarzanym co tydzień w jego dni, a zmiany w aplikacji go aktualizują. Przypomnienia przychodzą tylko z aplikacji, więc Google nie dodaje własnych, a treningi nigdy nie pojawiają się w aplikacji podwójnie. Ponowne dotknięcie usuwa z Kalendarza Google tylko treningi.",
    faq_q_sport_workout_gcal: "Czy moje treningi mogą pojawiać się w Kalendarzu Google?",
    workout_gcal_btn: "Kalendarz Google",
    workout_gcal_error: "Nie udało się zaktualizować Kalendarza Google – spróbujemy przy następnej zmianie",
    workout_gcal_not_connected: "Najpierw połącz Kalendarz Google w Ustawieniach",
    workout_gcal_off_toast: "Treningi usunięto z Kalendarza Google",
    workout_gcal_on_toast: "Twoje treningi są w Kalendarzu Google",
    faq_a_sport_workout_reminder: "Tak – w treningu, Przypomnienie: 10 minut, 30 minut lub godzinę wcześniej albo własny czas (trening musi mieć godzinę). Dzwoni jak inne przypomnienia, raz i w jednym miejscu: w aplikacji, jeśli jest otwarta, a jeśli nie – na telefonie. „Zrobione” zapisuje trening w historii, a „Jeszcze nie” przypomni znowu za 5 minut.",
    faq_q_sport_workout_reminder: "Czy mogę dostać przypomnienie przed treningiem?",
    workout_reminder_30min: "30 minut wcześniej",
    workout_reminder_label: "Przypomnienie",
    workout_reminder_need_time: "Dodaj godzinę, aby dostać przypomnienie",
    faq_a_sport_workout_share: "W ⋯ → Udostępnij tydzień zamienia się w szklany obrazek w kolorach Twojego motywu, z dyskretnym linkiem do aplikacji (na telefonie trafia od razu do menu udostępniania, na komputerze obraz się zapisuje). ⋯ → PDF do druku otwiera czystą stronę z całym tygodniem i kratką do odhaczenia przy każdym treningu i ćwiczeniu – wybierz „Zapisz jako PDF” albo wydrukuj. Plan pojawia się też w raporcie danych w Ustawieniach, w części Sport.",
    faq_q_sport_workout_share: "Jak udostępnić lub wydrukować tydzień treningów?",
    share_image_saved: "Obraz zapisany – możesz go dołączyć",
    share_save_image: "Zapisz obraz",
    workout_pdf_btn: "PDF do druku",
    workout_share_btn: "Udostępnij",
    faq_a_sport_workout_board: "W ⋯ → Tablica tygodnia każdy dzień to kolumna: przeciągnij trening na inny dzień (na telefonie najpierw przytrzymaj). W treningu „Także w Mojej Rutynie” wstawia go do rutyny o jego godzinie i w jego dni, a zmiany synchronizują się w obie strony; z pozycji w Mojej Rutynie „Dodaj do moich treningów” robi odwrotnie. ✓ w jednym miejscu liczy się w obu, a w Moim Dniu trening widać tylko raz – w chipie obok wody.",
    faq_q_sport_workout_board: "Jak przenieść trening na inny dzień i połączyć go z Moją Rutyną?",
    routine_in_workouts_btn: "Otwórz w moich treningach",
    routine_to_workout_btn: "Dodaj do moich treningów",
    routine_to_workout_done: "Dodano do moich treningów 💪",
    workout_delete_confirm_routine: "Zniknie z planu i z Mojej Rutyny. Treningi zapisane już w historii zostają.",
    workout_moved: "Przeniesiono na: {day}",
    workout_routine_need_time: "Dodaj godzinę, aby wstawić to do Mojej Rutyny",
    workout_routine_toggle: "Także w Mojej Rutynie",
    workout_view_board: "Tablica tygodnia",
    workout_view_timeline: "Oś czasu",
    faq_a_sport_workout_plan: "W Śledzeniu Treningów, w „Moje treningi”: + Trening – rodzaj, dni, godzina, czas trwania, intensywność i miejsce (także „Inne”). Treningi siłowe, funkcjonalne i pływanie mogą mieć listę ćwiczeń, a „Odpoczynek” oznacza dzień odpoczynku. Można też zacząć od gotowego planu. Dzisiejszy trening jest pokazany duży, a pod nim cały tydzień; ✓ zapisuje go w historii treningów razem z intensywnością. W ⋯ ustawia się cel tygodniowy (treningi lub minuty) – każdy wykonany trening wrzuca swoją gwiazdkę do słoika.",
    faq_a_sport_workout_today: "W Moim Dniu, obok wody, mały chip pokazuje dzisiejszy trening – dotknięcie otwiera szczegóły, ✓ i ▶. ▶ uruchamia stoper, który działa też w chipie na ekranie głównym, a „Zakończ” zapisuje trening z prawdziwym czasem. Jeśli w New Me trwa wyzwanie „Dwa tygodnie ruchu”, zapisany trening liczy się w nim sam.",
