    dictation_network: "Ta przeglądarka nie może połączyć się ze swoją usługą dyktowania – spróbuj w Chrome albo Edge",
    dictation_no_mic: "Nie znaleziono mikrofonu – komputer potrzebuje podłączonego mikrofonu albo słuchawek z mikrofonem",
    dictation_no_speech: "Nie słychać mowy – spróbuj jeszcze raz, trochę bliżej mikrofonu",
    dictation_service_off: "Dyktowanie jest wyłączone w tej przeglądarce lub na tym komputerze – włącz je w ustawieniach komputera albo spróbuj w Chrome",
    faq_a_new_me_magic_themes: "Pięć błyszczących motywów, które są w New Me: Zaczarowany las, Gwiezdny pył, Różana wróżka, Magiczna zorza i Złoty zmierzch. Wybierz jeden w New Me (⚙️ Ustawienia > Kolory) albo w Ustawienia > Wygląd i ekran, a pędzel z brokatem pomaluje nim ekran. Magiczny motyw dodaje brokat w całej aplikacji i przy każdym dotknięciu. W każdej chwili możesz wrócić do dowolnego innego motywu.",
