    theme_magic_section_label: "Magiczne motywy New Me",
    apptour_focus_text: "Wszystko schodzi na bok poza jedną rzeczą na teraz – z dużym ✓. Potem pojawia się następna.",
    apptour_m_presets_text: "Twoje zapisane posiłki w jednym miejscu: wyszukiwanie, ostatnio używane, według pory dnia – a ＋ dodaje posiłek na dziś.",
    apptour_night_text: "🌙 przyciemnia całą aplikację, ☀️ przywraca dzień.",
    apptour_noteline_text: "Napisz i dotknij ➤ – zapisze się w notatkach. 📝 na początku przełącza na 🛒 zakupy albo 🍎 zapisany posiłek.",
    apptour_search_text: "Notatki, zakupy, kalendarz, przepisy, zeszyty, cele, tabele i książki – jedno wyszukiwanie znajdzie wszystko.",
    faq_a_new_me_ai_menu: "Przed menu ankieta pyta, jakie posiłki jesz i kiedy (2 posiłki + przekąska, 2 posiłki + lekka kolacja albo jedno i drugie), czy wieczorem jesz coś małego i o której, czego nie jesz i jak pijesz kawę lub herbatę. Potem AI układa 3 propozycje na każdy posiłek – każdą w wielkości jego części dnia, więc dzień nadal sumuje się dokładnie do 1300 lub 1500 – oraz pomysły na napoje, zapisywane jako twoje stałe napoje. Wybierz do 2 ulubionych na posiłek; propozycje z oryginalnego menu są tuż pod nimi, a w 🔄 Zamień pojawiają się po twoim osobistym menu. 🔄 Inne propozycje układa nowy zestaw (3 razy na ankietę). Aby zmienić odpowiedzi lub ułożyć nowe menu w dowolnej chwili: ⚙️ Ustawienia → ✨ Osobiste menu (AI).",
    faq_q_new_me_ai_menu: "Jak działa osobiste menu w New Me?",
