    apptour_s_gcal_inside_text: "Połącz Google Calendar raz, a wydarzenia i zadania będą synchronizowane w obie strony.",
    apptour_s_menu_text: "Wszystko, co możesz dostosować, jest tutaj – w pięciu grupach. Otwórzmy je 👇",
