    nm_sales_premium: "Zawiera całe Premium",
    nm_unlock_premium: "Całe Premium też jest już odblokowane.",
    settings_sub_status_newme: "Premium jest w cenie Twojego New Me.",
    room_back_to_shelf: "Do półki",
    faq_a_new_me_day_total: "Każdy dzień sumuje się dokładnie do planu: posiłki, około 150 kcal na kawę i napoje w ciągu dnia oraz to, co wybrano na wieczór – coś małego do zjedzenia albo coś do picia. Na wieczór wybierz do 3, które lubisz (na przykład banan, jogurt albo 2 kostki gorzkiej czekolady; albo herbata ziołowa, herbata z odrobiną mleka czy ciepłe mleko), a ich kalorie są odejmowane od posiłków. Każdy wybór sam się równoważy: mniejsza lub większa opcja, usunięty posiłek, małe śniadanie i mały posiłek, który do niego dochodzi, albo wieczór – różnica jest dodawana do posiłków albo od nich odejmowana, do każdego według jego wielkości, a pod każdym posiłkiem jest napisane ile (+ lub −) i co dodać albo odjąć. Posiłek już odhaczony zostaje taki, jak został zapisany. W ankiecie przy każdym posiłku widać jego poprawkę, a małe okienko pokazuje posiłki, napoje, wieczór i sumę. Ochota na coś innego tego dnia? Suma powinna zostać przy tych samych kaloriach albo mniejsza.",
    faq_q_new_me_day_total: "Jak dzień w New Me sumuje się dokładnie do 1300 / 1500 i gdzie liczą się napoje?",
