    nm_swap_balanced: "{n} kcal rozłożone na posiłki, żeby dzień dał {plan}",
    books_quotes_chip: "Cytaty",
    faq_a_book_quotes: "Na półce w sekretnym pokoju (Cytaty) albo przez mały znaczek 💬 Cytaty w Kąciku czytelniczym – to ta sama lista. Dotknij „+ Cytat”, wpisz zdanie i wybierz książkę z Kącika czytelniczego albo wpisz inny tytuł przez „✏️ Inne”; autor jest opcjonalny. ✏️ edytuje cytat, a 🗑️ go usuwa. Cytaty to zakładki, które się przesuwa – 🎨 u góry zmienia je na zdjęcia albo ścianę kart.",
    faq_a_room_wish_jar: "Na półce w sekretnym pokoju stoi szklany słoik na marzenia. Dotknij małego słoika na najwyższej półce (albo Półka > Słoik życzeń) i napisz, jak chcesz, żeby wyglądało twoje życie – śmiało, bez dobrze i źle. Każde życzenie składa się w karteczkę i wpada do słoika. „Wylosuj karteczkę” otwiera losową, a każdą karteczkę można też otworzyć osobno. Od drugiego otwarcia tego samego życzenia możesz zrobić z niego cel i podzielić go na małe kroki. Raz w tygodniu delikatnie pojawia się karteczka z jednym z twoich życzeń – bez presji, tylko przypomnienie, dokąd zmierzasz.",
    faq_q_book_quotes: "Gdzie trzymać cytaty z ukochanych książek?",
