    room_wish_written: "Napisano {date}",
    faq_a_saved_meals_page: "Zapisane posiłki mają własną stronę: Odżywianie i Wskaźniki > ⭐ Zapisane posiłki (albo ⭐ w menu). Wyszukiwarka u góry znajduje posiłek po nazwie lub składniku, „Ostatnio używane” pokazuje, co dodano ostatnio, a karty (Śniadanie, Obiad, Kolacja, Zupy…) pokazują każdą porę dnia. „+ Dziś” dodaje posiłek do dzisiejszego Dziennego Rejestru Posiłków, w następne wolne miejsce. Dotknij posiłku, aby go edytować lub usunąć, a ＋ u góry dodaje nowy.",
    faq_q_saved_meals_page: "Gdzie znajdę zapisane posiłki i jak nimi zarządzać?",
