    presets_tab_snack: "Przekąski",
    presets_tab_soup: "Zupy",
    presets_tab_sweet: "Słodycze",
    faq_a_notes_sticky_look: "Notatki to krótka lista szklanych kart – 🎨 u góry Notatek zmienia wygląd wszystkich Notatek: listy, przycisków dni u góry i okna, w którym pisze się notatkę – szkło, prosta lista, fiszki albo taśma washi. Przeciągana notatka zachowuje dokładnie swój własny wygląd i kolor. Dotknij tekstu notatki, aby ją otworzyć – tam możesz ją edytować, zmienić kolory i zobaczyć, kiedy była ostatnio pisana. Dotknij ○, gdy sprawa jest załatwiona, a × przenosi ją do archiwum (🗑️ na dole listy ją przywraca). Przeciągnij ją za ⠿, aby zmienić kolejność, przenieść pod „Później” albo na dzień u góry. ! oznacza notatkę jako pilną – płynnie przesuwa się ona do pierwszych wierszy z małą etykietą „Pilne”; kolejne dotknięcie zdejmuje oznaczenie.",
    faq_q_notes_sticky_look: "Jak otworzyć, edytować albo usunąć notatkę?",
    note_to_archive_btn: "Przenieś do archiwum",
    faq_a_routine_clash: "Jeśli o tej godzinie w te same dni jest już jakiś element, pojawiają się dwie opcje: „Zamień” – nowy element zajmuje tę godzinę, a dla wcześniejszego wybierasz inną (przy edycji istniejącego elementu podpowiadana jest jego poprzednia godzina, więc oba po prostu się zamieniają), albo „Oba” – oba zostają o tej samej godzinie, jeden pod drugim. Jeśli dni są różne (np. jeden od niedzieli do czwartku, a drugi w piątek), o nic nie pytamy.",
    faq_q_routine_clash: "Co się stanie, gdy ustawię element rutyny na zajętą już godzinę?",
    routine_clash_both: "✌️ Oba – oba o {time}",
    routine_clash_move_btn: "Przenieś i zapisz",
    routine_clash_move_to: "Na którą godzinę przenieść „{title}”?",
    routine_clash_replace: "🔄 Zamień – i przenieś „{title}” na inną godzinę",
    routine_clash_title: "O {time} jest już: {title}",
    faq_a_new_me_coffee: "Pod dzisiejszym menu jest krótkie podsumowanie: ile kalorii mają razem wszystkie dzisiejsze posiłki, ile zostało na kawę i napoje, oraz przyciski wybranej kawy i napojów – jedno dotknięcie dodaje do sekcji Napoje. W „Wybierz do 3, które lubisz” pod przyciskami (i w ankiecie) wybierasz, co się pokazuje: woda / woda gazowana, herbata ziołowa, napój diet, czarna / americano (~5), herbata z odrobiną mleka (~25), kawa na wodzie z mlekiem lub napojem roślinnym do 100 ml (~50), lekka gorąca czekolada, ciepłe mleko albo zwykła kawa / latte (~120).",
    faq_q_new_me_coffee: "Gdzie dodać kawę i skąd wiadomo, ile zostało na dziś?",
