    nm_late_idea_yogurt: "Jogurt 0%",
    nm_late_ideas: "Na przykład: {ideas}",
    nm_late_ideas_none: "Dziś zostało bardzo mało – herbata, woda albo czarna kawa",
    nm_late_room_line: "Coś małego przed snem · dziś zostało ~{n} kcal",
    faq_a_recipe_examples: "Pod twoimi przepisami są przykładowe przepisy: śniadania, sałatki, zupy, dania główne, dodatki, przekąski, desery i dania wegańskie, każdy z czasem przygotowania, kaloriami na porcję i tym, ile gramów waży jedna porcja. Dotknij przepisu, aby go otworzyć, a „Zapisz w Moich Przepisach” tworzy twoją własną kopię, którą można edytować. Etykiety kategorii filtrują, a ponowne dotknięcie tej samej etykiety pokazuje wszystko.",
    faq_a_recipe_grams: "W przepisie, obok kalorii, jest napisane „1 porcja ≈ X g”. We własnych przepisach wpisz „Gramy na porcję” (i czas przygotowania, jeśli chcesz) w formularzu przepisu – oba pola są opcjonalne, a czas widać na kolorowym pasku przepisu.",
    faq_q_recipe_examples: "Czym są przykładowe przepisy w Moich Przepisach?",
    faq_q_recipe_grams: "Jak sprawdzić, ile gramów ma jedna porcja?",
    recipe_category_vegan: "Wegańskie",
    recipe_grams_placeholder: "Gramy na porcję",
    recipe_meta_grams: "1 porcja ≈ {n} g",
    recipe_meta_grams_short: "{n} g",
    recipe_meta_minutes: "{n} min",
    recipe_minutes_placeholder: "Czas przygotowania (minuty)",
    recipe_save_example_btn: "Zapisz w Moich Przepisach",
    recipe_saved_example: "✓ Zapisano w Moich Przepisach",
    recipe_saved_example_toast: "Zapisano w Moich Przepisach – tam można go edytować",
    recipes_examples_title: "Przykładowe przepisy",
    faq_a_recipe_scan_multi: "Tak. W „Dodaj Przepis” dotknij 📷 i wybierz jedno zdjęcie lub kilka (do 6; PDF też działa). Każde pojawi się na krótkiej liście, gdzie wybierasz, co na nim jest: Wszystko, Składniki lub Przygotowanie, a „➕ Jeszcze jedno zdjęcie” dodaje kolejne. Potem dotknij „✨ Zeskanuj przepis”: AI połączy wszystko w jeden przepis, po kolei i bez powtórzeń, i liczy się to jako jedno skanowanie. Kilka zdjęć wybranych w 📷 Zdjęcie w asystencie AI też otwiera się tutaj.",
    faq_q_recipe_scan_multi: "Czy można zeskanować jeden przepis z kilku zdjęć, np. osobno składniki i przygotowanie albo dwie strony?",
    recipe_scan_add_more: "➕ Jeszcze jedno zdjęcie",
    recipe_scan_part_all: "Wszystko",
    recipe_scan_part_ingredients: "Składniki",
    recipe_scan_part_steps: "Przygotowanie",
    recipe_scan_remove_photo: "Usuń zdjęcie",
    recipe_scan_run_btn: "✨ Zeskanuj przepis",
    recipe_scan_too_many: "Do {n} zdjęć na przepis",
    faq_a_note_written_at: "Dotknij tekstu notatki, aby ją otworzyć. W środku, pod tekstem, widać, kiedy została ostatnio napisana, z dokładną datą i godziną. Aktualizuje się tylko po zmianie samego tekstu: archiwizacja i przywrócenie, zaznaczenie ✓, kolory ani przesuwanie notatki tego nie zmieniają.",
    faq_q_note_written_at: "Jak sprawdzić, kiedy notatka została napisana?",
    note_written_at: "Ostatnio napisana: {date}",
    faq_a_new_me_month: "W magicznym plecaku → Kalendarz miesiąca: każdy dzień ma kolor zależny od liczby odhaczonych posiłków, strzałki ‹ › przełączają miesiące, a pod kalendarzem jest średnia dzienna kalorii z miesiąca. Dotknięcie dnia pokazuje, ile posiłków odhaczono i ile kalorii zjedzono tego dnia.",
    faq_q_new_me_month: "Gdzie w New Me zobaczę miniony miesiąc i średnie kalorie?",
    nm_month_avg: "Średnia z miesiąca: {kcal} kcal dziennie · dni z zapisem: {n}",
    nm_month_day_empty: "Tego dnia nic nie zapisano.",
    nm_month_day_line: "Odhaczone posiłki: {checks} · kalorie: {kcal}",
    nm_extra_line_small: "{n} kcal do tego posiłku, z małego śniadania – np. {ideas}",
    faq_a_new_me_small_breakfast: "Lekkie śniadanie (około 170 kcal): pita orkiszowa (do 100 kcal) z pastą albo serem, plus warzywo – wybierz do 3, które lubisz, na przykład 1 łyżeczkę kremu czekoladowego, 1 łyżeczkę masła orzechowego albo plasterek sera żółtego (do 22%). Ponieważ jest małe, dochodzi do niego „Do tego mały posiłek” o innej porze (na przykład półtorej godziny później, 11:30 → 13:00 – można wybrać inną porę): jeszcze jedna pita z pastą, jogurt proteinowy z owocem, wafle ryżowe z twarożkiem, płatki z mlekiem albo pół pity z jajkami – do około 200 kcal, z własnym ✓. To, co jeszcze zostaje, dzieli się między pozostałe posiłki, a każdy posiłek pokazuje, ile mu doszło, więc suma dnia zostaje jak w planie. Można je wybrać w ankiecie albo zmienić na nie tylko na dziś przez 🔄 – na przykład gdy śniadanie się opóźnia.",
    faq_q_new_me_small_breakfast: "Co to jest „małe śniadanie” w menu New Me?",
