    weather_sky_storm: "Burza",
    faq_a_ai_icon: "Tak – w Ustawieniach > Wygląd i ekran. Domyślna jest miękka bańka, a z Premium możesz wybrać też unoszący się mózg albo robota.",
    faq_a_new_me_favorites: "Tak. W ankiecie (i przy jej ponownym wypełnianiu z ustawień) możesz wybrać do 2 opcji na każdy posiłek. Pierwsza jest w menu, a pod nią linia „albo” z drugą – dotknięcie jej zmienia posiłek na nią tylko na dziś. A jeśli śniadanie nie zostało zjedzone na czas, „⏰ Później” przenosi je na później w ciągu dnia, bez zmiany kalorii.",
    faq_a_theme_mode: "Niektóre motywy specjalne wyglądają najładniej w ciemnym trybie – Akwarela, Zorza polarna, Barbie i dwa motywy z brokatem – więc wybranie jednego z nich przełącza aplikację na tryb ciemny, a wybranie dowolnego innego motywu (także rakiety) – na jasny. Czarny i Ciemnoszary zostają ciemne. Potem zawsze możesz to zmienić 🌙 w menu albo Trybem Jasnym w ustawieniach.",
    faq_a_water_month: "W śledzeniu wody. Przy każdym wpisie w dzisiejszym zapisie widać godzinę jego dodania, a „Tabela miesięczna” otwiera cały miesiąc: każdy dzień pokazuje, ile litrów wypito (✓, gdy osiągnięto dzienny cel), a dotknięcie dnia pokazuje jego wpisy z godzinami.",
    faq_q_ai_icon: "Czy można zmienić ikonę asystenta AI?",
    faq_q_new_me_favorites: "Czy w New Me można wybrać dwie ulubione opcje na posiłek?",
    faq_q_theme_mode: "Dlaczego po wyborze motywu aplikacja zrobiła się ciemna (albo jasna)?",
    faq_q_water_month: "Gdzie zobaczę, ile wody wypito każdego dnia?",
