    nm_pdf_meals: "Ułożony na 4 posiłki dziennie",
    nm_times_same_kcal: "Bez względu na wybór kalorie dnia zostają te same: to, co odpada, dzieli się między pozostałe posiłki.",
    dev_sim_panel_title: "PM – tylko dla Ciebie",
    faq_a_new_me_weight_optional: "Nie. Zarówno obecna, jak i docelowa waga w ankiecie są opcjonalne. Jeśli później dodasz ważenie (⚖️ Waga w „Mojej podróży” w New Me lub w dzienniku wagi), postęp liczy się od pierwszego.",
    faq_q_new_me_weight_optional: "Czy w New Me trzeba podać wagę?",
    nm_unlock_desc: "Menu, wyzwania i cała droga są gotowe – krok po kroku, razem.",
    nm_unlock_title: "New Me odblokowane!",
    room_reveal_star: "W teleskopie na dachu zapaliła się nowa gwiazda ✨",
    faq_a_room_records: "Gramofon stoi w pokoju od samego początku, na pniaku przy fotelu. Jego płyty otwierają na YouTube oficjalne teledyski wielkich hitów ostatnich lat, a pod nimi jest pięć spokojnych melodii, które grają tu, w pokoju – płyta kręci się, gdy grają, a „⏹ Zatrzymaj” wyłącza muzykę.",
    faq_a_room_roof_gifts: "Przychodzą z 8. kluczem. Dotknięcie teleskopu pozwala przez niego popatrzeć: nocne niebo z bliska – przeciągaj (albo używaj strzałek), żeby się rozejrzeć – a ukończone wyzwania układają się w nim w gwiazdozbiór, jedna gwiazda na każde wyzwanie; dotknięcie gwiazdy pokazuje, które to było. Dotknięcie małej skrzyni otwiera ją – na razie jest pusta – a kolejne dotknięcie ją zamyka.",
    faq_q_room_records: "Co jest na gramofonie w sekretnym pokoju?",
    faq_q_room_roof_gifts: "Czym są teleskop i skrzynia na dachu?",
    room_chest_letter: "Mały list dla ciebie",
    room_chest_letter_1: "Każdy mały krok na tej drodze był prawdziwy – i każdy się liczy.",
    room_chest_letter_2: "Życzliwość dla siebie to część drogi, a nie przerwa w niej.",
    room_chest_letter_3: "Są dni lżejsze i dni cięższe. Obecność w jednych i w drugich to prawdziwa siła.",
    room_chest_letter_4: "Odpoczynek jest dozwolony. Odpoczynek to też krok naprzód.",
    room_chest_letter_5: "Zmiany, które zostają, są ciche – budują się dzień po dniu.",
