    dev_sim_lock: "Zablokuj – zobaczyć jak przed zakupem",
    dev_sim_locked_toast: "🔒 Zablokowane – tak to wygląda przed zakupem",
    faq_a_new_me_preview: "Tak. Strona New Me zaczyna się krótkim filmem o tym, co dzieje się w środku: ankieta, lampy w korytarzu, plecak, wyzwania i klucze. Pod nim jest wszystko, co zawiera, podgląd jednego dnia i krótkie odpowiedzi.",
    faq_q_new_me_preview: "Czy można zobaczyć New Me przed zakupem?",
    nm_trailer_c1: "Krótka ankieta – i twoje menu jest gotowe",
