    nm_trailer_play: "Odtwórz film",
    nm_trailer_replay: "Obejrzyj ponownie",
    ai_chat_food_edit: "✏️ Popraw kalorie / białko",
    ai_chat_food_invalid: "Kalorie muszą być liczbą większą od 0",
    ai_chat_food_updated: "Zaktualizowano:",
    faq_a_ai_chat_food_fix: "Tak. Pod odpowiedzią na czacie dotknij ✏️ Popraw kalorie / białko, zmień liczby i dotknij Zapisz. Zmienia się tylko to, co właśnie dodano – nawet jeśli dołączyło do przekąski, która już była. AI może się mylić, więc warto szybko sprawdzić.",
    faq_a_new_me_home_btn: "Przy New Me mały 💎 obok trybu skupienia, u góry ekranu głównego, otwiera dzisiejsze menu. Dzisiejsze posiłki widać też w Moim Dniu, każdy z ✓.",
    faq_a_routine_item_days: "Tak. Dotknij punktu w Mojej Rutynie i wybierz jego dni w 📅 Dni – na przykład tylko od poniedziałku do piątku. W pozostałe dni nie pojawia się w Moim Dniu i nie ma ✓; w Mojej Rutynie zostaje, bledszy, z dniami obok. Karta, która pyta o punkt po 3 dniach bez ✓, liczy tylko jego dni.",
    faq_q_ai_chat_food_fix: "Czy można poprawić kalorie lub białko, gdy asystent zapisze jedzenie?",
    faq_q_new_me_home_btn: "Gdzie jest New Me na ekranie głównym?",
    faq_q_routine_item_days: "Czy jeden punkt w Mojej Rutynie może być tylko w wybrane dni?",
    routine_item_days_label: "📅 Dni",
    home_note_meal_ph: "Znajdź zapisany posiłek…",
    menu_quick_search: "Szybkie wyszukiwanie",
    nm_times_hint: "Wskazówka: możesz ustawić najpóźniejszą godzinę, o której zwykle jesz każdy posiłek – na przykład 9:00, jeśli często jesz około 8.",
    room_game_marquee: "Po drodze – zatrzymaj się i ciesz się",
    room_sand_erase_aria: "Potrzyj, aby zetrzeć napis",
    faq_a_home_note_line: "Napisz w linii na środku ekranu głównego i dotknij ➤ (lub Enter) – zapisze się w Notatkach. Dotknij 📝 na początku linii, a zmieni się w 🛒: wtedy to, co napiszesz, trafi na Listę Zakupów. Dotknij jeszcze raz, by był 🍎: wpisz kilka liter, pojawią się pasujące zapisane posiłki, a dotknięcie zapisze jeden w dzisiejszych posiłkach. Z 🎤 możesz to po prostu powiedzieć.",
    faq_a_night_mode: "Otwórz menu ☰ i dotknij 🌙 u góry – cała aplikacja robi się ciemna. ☀️ w tym samym miejscu przywraca dzień. Jest to też w Ustawieniach, w Trybie Jasnym.",
    faq_q_home_note_line: "Jak napisać szybką notatkę z ekranu głównego?",
    faq_q_night_mode: "Jak przełączyć się na tryb nocny?",
    menu_day_mode: "Tryb dzienny",
    menu_night_mode: "Tryb nocny",
    faq_a_secret_room_yoga: "Na końcu ścieżki w lesie stoi świecąca brama. Za nią, przy wodospadzie, leśne stworzenia – Lumi, Puffi, Nixie i Sparklet – siedzą na swoich matach w półkolu, a Flora, nauczycielka jogi, siedzi naprzeciw nich na jedynej macie na kamieniu. Dotknij Flory: otwiera oczy, wszystko się przybliża i rozmowa zaczyna się powoli, z czasem na czytanie – Flora pyta, jak się wszyscy mają, każde stworzenie odpowiada we własnym imieniu (przy każdej linijce widać mały obrazek postaci, która akurat mówi), a potem ona pyta ciebie, jak ci z bliskimi ludźmi. Rozmowa toczy się dalej według twoich odpowiedzi – dobrzy ludzie, ktoś, z kim jest trudno, albo trochę samotności. Każda droga kończy się małą misją (może trafić prosto do Mojego Dnia; gdy misja polega na napisaniu czegoś, jest miejsce, żeby to napisać, i zapisuje się to w magicznym pamiętniku) i pozycją z trzema oddechami razem. ↩ cofa o krok, a ✦ zaczyna nową rozmowę. Kolejny klucz otwiera wodospad: gdy usiądziesz na kamieniu, wszystko znika i zostaje tylko szum wody. Gdy pochylisz się nad stawem, z wody wypływa pytanie – co zrobiłoby dziś twoje prawdziwe ja? – a odpowiedź staje się małym zadaniem w Moim Dniu. To miła chwila, a nie zastępstwo rozmowy ze specjalistą.",
    faq_q_secret_room_yoga: "Co dzieje się na jodze w lesie?",
    room_back_to_forest: "Wróć na ścieżkę",
    room_back_to_yoga: "Wróć do jogi",
    room_item_waterfall: "Wodospad",
    room_waterfall_pool_aria: "Dotknij wody",
    room_waterfall_rock_aria: "Usiądź na skale",
    room_yoga_guide_aria: "Porozmawiaj z Florą",
    yg_g_alone: "Dziękuję, że się dzielisz. Każdemu czasem się to zdarza.",
    yg_g_alone_q: "Co byłoby dobre, choćby troszkę?",
    yg_g_critic: "Krytyka potrafi kłuć długo. Mówi o jednej chwili – nie o całym człowieku.",
    yg_g_end: "Dziękuję za ten czas w kręgu. Możesz wrócić, kiedy tylko zechcesz.",
    yg_g_gate: "Wolno postawić granicę. Granica to nie mur – to furtka.",
    yg_g_good: "Jak pięknie 💛 Kto był dla ciebie dobry w tym tygodniu?",
    yg_g_good_msg: "Dobrym ludziom warto to mówić. Małe dziękuję może im zrobić cały dzień.",
    yg_g_hard: "Dziękuję, że to mówisz. Co ciąży najbardziej?",
    yg_g_listen: "Kiedy nikt nie słucha, to męczy. Twój głos się liczy, nawet gdy jest cichy.",
    yg_g_new: "Nowe znajomości zaczynają się od małego cześć. Zajęcia, spacer, grupa – jeden krok.",
    yg_g_old: "Ktoś, kto już cię zna, to ciepłe miejsce. Wystarczy krótka wiadomość.",
    yg_g_start: "A teraz twoja kolej 🌿 Jak ci ostatnio z bliskimi ludźmi?",
    yg_g_used: "Gdy dajemy i nic nie dostajemy w zamian, coś w środku się męczy. To w porządku to zauważyć.",
