    yg_p1_start: "Mój tydzień był zabiegany, ale dobra przyjaciółka zadzwoniła w samą porę.",
    yg_p2_hard: "Też tak miałem. Samo powiedzenie tego na głos już pomogło.",
    yg_p2_start: "Mnie też pomaga słuchanie wszystkich.",
    yg_pose_child: "Teraz pozycja dziecka 🌙 Kolana w dół, czoło na macie – bezpieczne miejsce do oddychania. Trzy oddechy razem.",
    yg_pose_heart: "Teraz otwarte serce 💗 Ramiona do tyłu, klatka szeroko. Trzy oddechy razem.",
    yg_pose_tree: "Teraz pozycja drzewa 🌳 Stoimy stabilnie, stopa na drugiej nodze, ręce w górę. Trzy oddechy razem.",
    yg_task_good: "Wysłać dziś krótką wiadomość z podziękowaniem",
    yg_task_hard: "Napisać jedno zdanie, które chcę powiedzieć",
    yg_task_new: "Znaleźć jedno miejsce, by poznać nowych ludzi",
    yg_task_old: "Wysłać komuś „myślę o tobie”",
    nm_time_hour: "Godzina",
    nm_time_minutes: "Minuty",
    routine_time_taken: "O tej godzinie coś już jest: {title}",
    faq_a_new_me_times: "W ankiecie na początku i w każdej chwili w ustawieniach New Me → „Pory posiłków”. Jeśli w rutynie są już pory posiłków, zostaną stamtąd wzięte – a posiłki z rutyny można ukryć i pokazać w ich miejscu posiłki New Me. Jeśli nie, wybierasz, ile posiłków dziennie (2 posiłki + przekąska / 2 posiłki + lekka kolacja / 2 posiłki + przekąska + lekka kolacja) i kiedy każdy. Przy „2 posiłki + przekąska” to obiad o 11:30, przekąska o 16:00 i kolacja o 19:00 (każdą porę można zmienić). To są pory posiłków wszędzie: w korytarzu, w Moim Dniu, w Mojej Rutynie i w przypomnieniach. Bez względu na wybór kalorie dnia zostają te same: to, co odpada, dzieli się między pozostałe posiłki.",
    faq_q_new_me_times: "Jak ustawić pory posiłków w New Me?",
    nm_times_count: "Ile posiłków dziennie?",
    nm_times_from_routine: "Tak, weź je z mojej rutyny",
    nm_times_hide: "Ukryj posiłki z mojej rutyny i pokaż w ich miejscu posiłki New Me",
    nm_times_later: "Później",
    nm_times_manual: "Nie, wybierz tutaj",
    nm_times_none_found: "W rutynie nie ma jeszcze posiłków – wybierz tutaj ile i kiedy.",
    nm_times_q: "Czy w twojej rutynie są stałe pory jedzenia?",
    nm_times_saved: "Pory posiłków zapisane",
    nm_times_title: "Pory posiłków",
    faq_a_routine_exact_time: "Tak. Gdy opisujesz AI rutynę z dokładną godziną (np. „16:10 trading”), zapisuje się dokładnie tak – bez zaokrąglania do pełnej godziny. Wszystko, co jest wpisane w rutynę, zawsze widać na tablicy, nawet jeśli ta godzina nie jest wybrana w ustawieniach godzin, a usunięcie godziny, w której coś jest, najpierw pyta o potwierdzenie. Godzinę można też zmienić ręcznie: dotknij godziny w oknie elementu i wybierz godzinę oraz minuty.",
    faq_q_routine_exact_time: "Czy moja rutyna może mieć dokładną godzinę, np. 16:10?",
