    routine_daysoff_ai_ph: "np. pobudka o 9, długie śniadanie, spacer po południu, wieczorem rodzina",
    routine_daysoff_clean: "Bez planu – zostaje pusto",
    routine_daysoff_clear_q: "Wyczyścić rutynę dni wolnych?",
    routine_daysoff_done: "Rutyna na dni wolne jest gotowa 🌴",
    routine_daysoff_done_clean: "Dni wolne zostają puste 🌿",
    routine_daysoff_empty: "Dzień wolny – bez planu 🌿",
    routine_daysoff_own: "Moja własna rutyna",
    routine_daysoff_pick_days: "Wybierz co najmniej jeden dzień",
    routine_daysoff_what: "A jaka jest rutyna w te dni?",
    routine_daysoff_which: "Które dni?",
    faq_a_secret_room_diary: "Tylko ty. Strony pamiętnika zapisują się na koncie, więc są na każdym urządzeniu i nikt inny ich nie widzi. Otwiera go magiczny pamiętnik na biurku w sekretnym pokoju, a także pamiętnik w muzycznym kąciku. Pod nową stroną jest zwinięta tabela miesiąca: kropka oznacza każdy dzień, w którym jest strona, a dotknięcie dnia otwiera jego strony – tam można też usunąć stronę. Gdy pamiętnik jest już otwarty, można go też dodać do menu głównego – przełącznikiem w samym pamiętniku albo w ustawieniach New Me.",
    faq_a_secret_room_places: "Każde wejście przy leśnej bramie otwiera się własnym kluczem. Za nimi: weranda z widokiem na morze (na stoliku lampa Aladyna – jedno dotknięcie i w magicznej mgle wyłania się z niej duch lasu, krąży dookoła i zaczyna rozmowę o twoim życzeniu – zobacz „Co robi dżin z lampy?”), gitara i pamiętnik (gitara gra krótką, spokojną melodię i sama cichnie, a każda z trzech płyt wiszących na drzewie gra własną magiczną melodię – ponowne dotknięcie ją zatrzymuje – a w pamiętniku na pniaku się pisze), pokój oddechu (spokojne jezioro o zachodzie słońca – na wodzie unosi się lotosowy lampion: dotknij go, napisz życzenie, a on odpływa z nim daleko w głąb jeziora; czarodziejską różdżką można napisać na piasku to, co chce się odpuścić, a to zostanie, dopóki nie zetrzesz tego palcem) i ścieżka w lesie (otwiera się nocą, a dotknięcie latarni przełącza na dzień; na ławce można usiąść, a dotknięcie tabliczki przybliża ją – tablica z sześcioma małymi pytaniami do zaznaczenia). Przy zamkniętym wejściu widać, ilu kluczy brakuje. Na końcu ścieżki świecąca brama prowadzi do jogi przy wodospadzie – a stamtąd do samego wodospadu.",
    faq_q_secret_room_diary: "Kto widzi pamiętnik?",
