    dev_weather_preview_label: "Podgląd – tylko na twoim koncie:",
    faq_a_ai_chat: "Dotknij dymka, a otworzy się czat. Wybierz, co zrobić – coś do kalendarza, posiłek, zdjęcie przepisu lub nową tabelę – albo po prostu napisz, a asystent sam to rozpozna. Możesz też dotknąć 🎙️ i mówić zamiast pisać. W kalendarzu można wybrać jednorazowo, co tydzień lub codziennie. Odpowiedź pojawia się w czacie, a stamtąd można przejść do czegoś innego albo otworzyć kalendarz / posiłki.",
    faq_a_new_me_hall: "New Me otwiera się przy bramie zaczarowanego lasu, a każde wejście to inne miejsce: okrągłe drzwi w ogromnym drzewie prowadzą do sekretnego pokoju, wydrążony pień – na werandę z widokiem na morze, domek-grzybek – do gitary i pamiętnika, mały wierzbowy łuk – do pokoju oddechu, duży wierzbowy łuk – do ścieżki w lesie, a kwiatowy łuk z drabiną prowadzi w górę, na gwiezdny dach, gdy ten się otworzy. Przy zamkniętym wejściu widać kłódkę. Nad ścieżką unosi się twoja postać, Sky, a dookoła są przyciski gry: następna misja, wyzwanie tygodnia, magiczny plecak z całym New Me, mapa świata i narzędzia. Dotknięcie kluczy u góry wyjaśnia, jak zdobywa się klucze.",
    faq_a_new_me_routine_meals: "Gdy w New Me są ustawione posiłki, a w Mojej Rutynie też są posiłki, New Me pyta, czy je ukryć i pokazać w ich miejscu posiłki New Me – żeby nic nie pojawiało się dwa razy. Wtedy Moja Rutyna pokazuje posiłki New Me o ich porach, z 💎 i ✓; dotknięcie nazwy posiłku otwiera okno wyboru innego posiłku lub zmiany jego godziny, od razu nad rutyną. Nic nie jest usuwane: wracają przez ⚙️ Ustawienia → Posiłki w rutynie w New Me albo po wyłączeniu „Synchronizuj z New Me” w ⚙️ Mojej Rutyny. Bez aktywnego New Me wracają same.",
    faq_a_room_computer: "To mały czat, który zaczyna się od pytania „Jak mija twój dzień do tej pory?” – dobrze, intensywnie czy ciężko – i idzie z tobą krok po kroku, aż do jednej małej misji na końcu (którą można też od razu dodać do Mojego Dnia). Odpowiedzi można dotykać albo pisać swobodnie – to, co napisane, łączy się z najbliższą odpowiedzią. „↩ Wstecz” cofa o krok, żeby odpowiedzieć inaczej, a „Nowy czat” zaczyna od nowa w dowolnej chwili. Po intensywnym albo ciężkim dniu można wrócić do komputera później tego samego dnia: „Znowu tu jestem...” kontynuuje rozmowę. Zielona lampka na dole wyłącza i włącza komputer. Zapisywane są tylko wybory, tylko na tym urządzeniu i tylko do końca dnia.",
    faq_q_ai_chat: "Jak rozmawiać z asystentem?",
    faq_q_new_me_hall: "Czym jest korytarz w New Me?",
    faq_q_new_me_routine_meals: "Dlaczego Moja Rutyna pokazuje posiłki New Me?",
    faq_q_room_computer: "Jak działa komputer w sekretnym pokoju?",
