    dictation_mic_denied: "Mikrofon jest zablokowany – zezwól na niego przez 🔒 obok adresu w przeglądarce albo w ustawieniach telefonu",
    faq_a_dictation: "Tak – dotknij mikrofonu 🎤 w rogu szybkiej notatki lub strony do pisania w zeszycie i mów: słowa zapisują się w trakcie mówienia, w języku aplikacji. Dotknij ponownie, aby zatrzymać. Za pierwszym razem przeglądarka poprosi o zgodę na mikrofon. Działa w Chrome / Androidzie i w Safari na iPhonie. Na komputerze potrzebny jest mikrofon i przeglądarka, np. Chrome, Edge albo Safari – jeśli czegoś brakuje, komunikat powie dokładnie czego.",
    faq_q_dictation: "Czy mogę mówić zamiast pisać?",
    faq_a_secret_room: "Pokój tylko dla ciebie, w New Me – dom w środku ogromnego drzewa. Widzisz jedną ścianę naraz i obracasz się strzałkami (albo przesunięciem). Pierwszy klucz przychodzi po ✓ przy posiłku w 3 różne dni i otwiera drzwi – a z nimi cały pokój: komputer, grę, gramofon, półkę z biblioteką w środku i kota. Potem każde ukończone wyzwanie (także wyzwanie tygodnia) daje klucz, który otwiera kolejne miejsce: gwiezdny dach, werandę z widokiem na morze, gitarę i pamiętnik, pokój oddechu, ścieżkę w lesie z jogą, wodospad i niespodziankę na dachu – a 8. przynosi butelkę z morza z listem z przeszłości w środku. Gdy coś się otwiera, strzałka pokazuje drogę do niego. Otwierają się też małe drzwiczki na dole automatu do gier – na razie szafka za nimi jest pusta. Na gwiezdnym dachu dotknięta gwiazda spada jak spadająca gwiazda, a kot siedzi na poduszce.",
