    room_wall_window_hint: "Dotknij przedmiotu, by podejść bliżej · strzałki obracają pokój",
    room_wall_window_title: "Okno i komputer",
    faq_a_steps_in_sport: "Na górze Śledzenia Treningów, w małym pasku: kroki z dzisiaj i z tego tygodnia. Kroki będą liczone automatycznie, gdy aplikacja połączy się z Google Fit / Apple Health w wersji na telefon – wyjaśnia to przycisk 🔗 obok.",
    faq_q_steps_in_sport: "Gdzie jest dzienny licznik kroków?",
    sport_steps_today_label: "kroków dziś",
    sport_steps_week_label: "w tym tygodniu",
    faq_a_reminders_one_place: "Każde przypomnienie przychodzi raz i w jedno miejsce. Jeśli aplikacja jest otwarta przed tobą (na komputerze, iPadzie lub telefonie), pojawia się tam; w przeciwnym razie przychodzi jako powiadomienie tylko na telefon. '✅ Zrobione, dzięki!' lub 'Rozumiem!' w dowolnym miejscu zamyka je na wszystkich urządzeniach i już nie wraca. 'Jeszcze nie' odkłada je: wraca co 5 minut, za każdym razem w jedno miejsce. Zaznaczenie zadania ✓ na liście też liczy się jako zrobione. Aby dostawać powiadomienia także na komputerze i tablecie, włącz 'Także na komputerze i tablecie' w Ustawienia > Powiadomienia.",
    faq_q_reminders_one_place: "Dlaczego przypomnienie przychodzi tylko raz i tylko na telefon?",
    reminder_all_devices_hint: "Domyślnie każde przypomnienie przychodzi raz i w jedno miejsce: na telefon albo na urządzenie, na którym aplikacja jest właśnie otwarta przed tobą. Zrobione lub Rozumiem w jednym miejscu zamyka je wszędzie.",
    reminder_all_devices_label: "Także na komputerze i tablecie",
    myday_water_info: "8 średnich / małych szklanek wody to średnio około 2 litrów",
    faq_a_good_things: "Wieczorem (od 18:00) pod datą pojawia się mały przycisk: zapisz do 3 dobrych rzeczy, które dziś się wydarzyły – nawet jedna wystarczy. Są zapisywane, a w „Poprzednich dniach” widać, co było wcześniej. „Nie dziś wieczorem” ukrywa go do jutra, a całkiem wyłączyć można w Ustawienia > Personalizacja i kalendarz.",
    faq_a_home_countdown: "Oznacz wydarzenie ⭐ w kalendarzu (gwiazdka obok niego na liście wydarzeń). Najbliższe oznaczone wydarzenie w ciągu następnych 100 dni pojawi się pod datą – „Za 3 dni · Urodziny mamy”, „Jutro · …” albo „Dziś · …”. Dotknij go, żeby przejść do tego dnia w kalendarzu.",
    faq_a_home_streak: "Liczy, przez ile dni z rzędu był co najmniej jeden ✓ – cokolwiek w sekcji Mój Dzień, w Mojej Rutynie, w Moich Celach albo w New Me. Pojawia się od 2 dni. Jeśli dziś nie ma jeszcze ✓, seria nie jest przerwana – zostaje cały dzień. A jeśli się skończy, po prostu cicho znika, bez wyrzutów sumienia.",
    faq_a_home_weather: "Włącz „Pogoda na niebie ekranu głównego” w Ustawienia > Personalizacja i kalendarz i zezwól na lokalizację. Wtedy niebo ekranu głównego pokazuje prawdziwą pogodę tam, gdzie jesteś – słońce (a nocą księżyc i gwiazdy), chmury, deszcz, śnieg, burzę albo mgłę – w każdym motywie, odświeżane mniej więcej co 40 minut. Przybliżona lokalizacja (zaokrąglona do około 1 km) zostaje tylko na twoim urządzeniu i jest sprawdzana przez nasz serwer w MET Norway. Domyślnie jest wyłączone. Pod przełącznikiem widać, jaka jest teraz pogoda na zewnątrz – na przykład ⛅ Częściowe zachmurzenie, dlatego na niebie jest i słońce, i chmury.",
    faq_q_good_things: "Co to jest „3 dobre rzeczy z dziś”?",
    faq_q_home_countdown: "Jak dodać odliczanie na ekranie głównym?",
    faq_q_home_streak: "Co to jest 🔥 „dni z rzędu” pod powitaniem?",
    faq_q_home_weather: "Jak włączyć pogodę na niebie ekranu głównego?",
    good_things_chip: "3 dobre rzeczy z dziś",
    good_things_chip_done: "3 dobre rzeczy ✓",
    good_things_hint: "Coś małego, co dziś było dobre – nawet jedna rzecz wystarczy.",
    good_things_past: "Poprzednie dni",
    good_things_past_empty: "Tutaj pojawią się poprzednie dni.",
