    home_streak_days: "Dni z rzędu: {n}",
    home_streak_title: "Dni z rzędu z co najmniej jednym ✓",
    settings_good_things_label: "„3 dobre rzeczy” wieczorem",
    settings_weather_hint: "Deszcz, chmury albo śnieg w tle ekranu głównego, zależnie od pogody tam, gdzie jesteś. Przybliżona lokalizacja zostaje na tym urządzeniu i jest sprawdzana przez nasz serwer w MET Norway.",
    settings_weather_label: "Pogoda na niebie ekranu głównego",
    weather_failed: "Nie udało się teraz sprawdzić pogody.",
    weather_location_denied: "Brak dostępu do lokalizacji – zezwól na nią w ustawieniach przeglądarki i spróbuj ponownie.",
    faq_a_home_focus: "Dotknij ◎ na górze ekranu głównego: znika wszystko oprócz jednej rzeczy na teraz – tego, co jest o tej godzinie, albo następnej rzeczy z dzisiejszej listy – z dużym ✓ i Szybką Notatką. Po ✓ pojawia się kolejna rzecz. Dotknij „Tryb skupienia ✕” na górze, aby wszystko wróciło.",
    faq_a_home_search: "Otwórz menu ☰ – wyszukiwanie jest na samej górze. Wpisz co najmniej 2 litery: wyniki pochodzą z notatek, listy zakupów, kalendarza, przepisów, zeszytów (tytuły i tekst stron), celów, tabel i książek, pogrupowane według rodzaju – dotknij jednego, aby od razu tam przejść.",
    faq_a_my_day: "Mój Dzień łączy to, co wcześniej było Rzutem Oka na Dzisiaj i Moją Rutyną, na jednej osi czasu. Na dole ekranu głównego widać, ile już zrobiono, co jest teraz lub następne (z szybkim ✓), a obok tytułu szklankę wody z +1. Dotknij (albo przesuń w górę), aby otworzyć cały dzień: na górze rzeczy bez godziny, potem wszystko według godzin – zadania, wydarzenia i spotkania z kalendarza, stałe tygodniowe pory, dzisiejsza rutyna, małe kroki twoich celów i posiłki New Me – z linią „teraz”. Filtruj według Zadań, Rutyny lub Spotkań i wydarzeń. ✓ tutaj to ten sam ✓ co wszędzie indziej (Moja Rutyna, Moje Cele, kalendarz) i otwiera stokrotkę w kąciku. „Edytuj rutynę” otwiera Moją Rutynę (jest też w menu), a „＋ Dodaj na dziś” dodaje zadanie na dziś. Dotknięcie tytułu „Mój Dzień” (albo paska u góry) znowu go zamyka.",
    faq_q_home_focus: "Czym jest tryb skupienia?",
    faq_q_home_search: "Jak szukać w całej aplikacji?",
