    faq_a_new_me_tour: "Zaraz po zakupie i krótkiej ankiecie krótki przewodnik pokazuje grę: górny pasek, następną misję, wyzwanie tygodnia, magiczny plecak i drzwi 1 do sekretnego pokoju. Można go obejrzeć ponownie w każdej chwili w ⚙️ Ustawienia > 🧭 Przewodnik po New Me – tam też można zmienić imię i nazwisko z ankiety. Przed zakupem przy New Me w menu widać 🔒, a dotknięcie otwiera stronę ze wszystkim, co jest w pakiecie.",
