    faq_a_new_me_advanced: "Tryb zaawansowany otwiera się razem z prezentem, po wszystkich 20 wyzwaniach, i można go włączać i wyłączać w 🎁 Twój prezent. Daje New Me złoty wygląd, swobodne układanie menu – każda zamiana pokazuje wszystkie opcje bez limitu kalorii – oraz ekran 📊 Rozszerzone statystyki: kalorie z ostatnich 30 dni na tle planu, dobre dni według dnia tygodnia, trend wagi z szacunkiem, kiedy cel zostanie osiągnięty, średnie wieczornego check-inu i historię wyzwań.",
