    nm_gift_intro: "Wszystkie {n} wyzwań, krok po kroku. Oto, co czekało:",
    nm_gift_title: "Twój prezent",
    faq_a_new_me_letter_gift: "Na początku New Me (albo później, w Wyzwaniach) można napisać list do siebie w przyszłości. Po zapieczętowaniu nie da się go przeczytać ani edytować, dopóki się nie otworzy: w butelce z morza w sekretnym pokoju albo po ukończeniu wszystkich 20 wyzwań – tam czeka też prezent.",
    faq_q_new_me_letter_gift: "Czym jest list z przeszłości?",
    faq_a_new_me_challenges: "🏆 Wyzwania to 20 wyzwań: 10 dużych (np. 5 dni bez cukru, tydzień bez węglowodanów albo schudnąć 4 kg w miesiąc – codziennie deficyt kaloryczny, trening i bez cukru) i 10 mini – małe nawyki na tydzień, jak kawa z cynamonem bez cukru. Przy wyborze wyzwania pojawia się pytanie, kiedy zacząć: dziś, jutro, w przyszłym tygodniu albo innego dnia. Jedno duże i jedno mini wyzwanie mogą trwać jednocześnie. Trwające wyzwanie pojawia się na górze menu i w sekcji „Mój Dzień”, z ✓ na dany dzień. Każdy tydzień wyzwania daje jeden dzień wolny (🍕), który go nie przerywa, a nieodhaczony dzień liczy się jako wolny – można odhaczyć dziś i wczoraj. Niektóre dni odhaczają się same: 20-minutowy trening w Śledzeniu Treningów albo posiłki z menu z ✓. Każde wyzwanie ma ⓘ z tym, co dokładnie się liczy (na przykład pełną listą węglowodanów) – w samym wyzwaniu i obok niego w sekcji „Mój Dzień”. Poniżej, w 🌱 Rozwoju osobistym, jest 48 małych wyzwań na jeden tydzień (nie liczą się do tych 20) – zobacz „Czym jest wyzwanie tygodnia?”.",
    faq_q_new_me_challenges: "Jak działają wyzwania w New Me?",
    nm_letter_too_short: "Jeszcze kilka słów 🙂",
    nm_letter_quiz_note: "Opcjonalne – można go napisać także później, w Wyzwaniach.",
    nm_letter_write: "✍️ Napisz list",
