    nm_ch_lose5_month_task: "Deficyt + trening + bez cukru",
    nm_ch_lose5_month_desc: "Trzy rzeczy każdego dnia: w budżecie kalorii (deficyt), trening i bez dodanego cukru. Liczą się dni – nie waga, która ma własne tempo.",
    nm_ch_lose5_month_title: "Schudnąć 4 kg w miesiąc",
    nm_ch_menu_21_task: "Posiłki z menu ✓",
    nm_ch_menu_21_desc: "Każdego dnia posiłki z menu dostają ✓ – co najmniej 3 albo wszystkie, gdy menu jest mniejsze. Zaplanowany swobodny posiłek się liczy, a dzień odhacza się sam.",
    nm_ch_menu_21_title: "21 dni według menu",
    nm_ch_no_sugar_21_desc: "Trzy tygodnie bez dodanego cukru – wystarczająco długo, by ochota na słodkie się uspokoiła. Owoce i naturalna słodycz mile widziane.",
    nm_ch_no_sugar_21_title: "21 dni bez cukru",
    nm_ch_no_snacking_14_task: "Tylko to, co w menu",
    nm_ch_no_snacking_14_desc: "Tylko to, co w menu, i napoje – bez podjadania między posiłkami. Głód? Szklanka wody lub herbata, a następny posiłek jest już blisko.",
    nm_ch_no_snacking_14_title: "Dwa tygodnie bez podjadania",
    nm_ch_home_food_14_task: "Dziś domowe jedzenie",
    nm_ch_home_food_14_desc: "Bez dostaw i jedzenia na wynos – coś zrobione w domu, nawet proste. Zaplanowany swobodny posiłek jest dozwolony.",
    nm_ch_home_food_14_title: "Dwa tygodnie domowego jedzenia",
    nm_ch_no_fried_14_task: "Dzień bez smażonego",
    nm_ch_no_fried_14_desc: "Bez frytek, smażonych kotletów i smażonych przekąsek – zamiast tego piekarnik, grill albo frytkownica beztłuszczowa.",
