    nm_ch_sport_14_desc: "Co najmniej 20 minut aktywności dziennie – spacer też się liczy. Trening zapisany w Śledzeniu Treningów sam odhacza dzień.",
    nm_ch_sport_14_title: "Dwa tygodnie ruchu",
