    nm_ch_no_carbs_7_desc: "Tydzień bez węglowodanów – w każdym posiłku miejsce węglowodanu zajmują dodatkowe warzywa i białko. Co liczy się jako węglowodan? Pełna lista jest pod ⓘ.",
