    nm_ch_rule: "Jeden dzień wolny na każdy tydzień wyzwania. Nieodhaczony dzień liczy się jako wolny – można odhaczyć dziś i wczoraj. Jedno duże i jedno mini wyzwanie mogą trwać jednocześnie.",
