    nm_ch_completed_label: "ukończonych wyzwań",
    nm_tile_challenges: "Wyzwania",
    faq_a_workout_calories: "Tak. Każdy trening dostaje szacunek spalonych kalorii – według rodzaju, czasu trwania i ostatniej wagi (przy bieganiu i jeździe na rowerze także według tempa, gdy wpisano dystans). Widać go na liście treningów i w podsumowaniu miesiąca (Spalone), a dodaje się do budżetu kalorii tego dnia: w Dziennym Rejestrze Posiłków, we Wskaźnikach Kalorii i Wagi oraz w pierścieniu New Me. To szacunek, dlatego ma znak ~.",
    faq_q_workout_calories: "Czy treningi liczą się do kalorii z dnia?",
    faq_a_new_me_flexible_menu: "Tak. W ankiecie i w ustawieniach wybierasz, ile posiłków dziennie – 2 posiłki + przekąska / 2 posiłki + lekka kolacja / 2 posiłki + przekąska + lekka kolacja – a ➖ na karcie posiłku go usuwa (zostają co najmniej 3); „➕ Dodaj z powrotem” go przywraca. Tak czy inaczej kalorie dnia zostają te same: to, co odpada, dzieli się między pozostałe posiłki, a pod każdym posiłkiem widać, ile mu doszło i co można dodać. ✏️ Edytuj na posiłku otwiera jego opis – zmień, co chcesz (np. bez chleba albo z jednym jajkiem więcej), a AI przeliczy kalorie i białko. 🔄 Zamień proponuje opcje z menu, ⭐ Zapisane i ✨ Napisz; każda zmiana może być tylko na dziś albo od teraz. A na końcu „Cały dzień” jest ➕ Dodaj jedzenie – napisz, co zostało zjedzone poza menu, a AI to przeliczy i doda do dziś (✕ usuwa).",
    faq_q_new_me_flexible_menu: "Czy mogę zmienić liczbę posiłków w New Me albo zjeść własny posiłek?",
