    vision_step_schedule_remove_btn: "Usuń z kalendarza",
    vision_step_schedule_save_btn: "Dodaj do kalendarza",
    vision_step_schedule_weekly_hint: "Wraca co tydzień tego samego dnia, dopóki raz go nie odhaczysz.",
    vision_step_schedule_weekly_label: "🔁 Co tydzień aż do wykonania",
    vision_step_schedule_date_label: "Data",
    vision_step_schedule_text: "Pojawi się tego dnia w sekcji Mój Dzień i w kalendarzu – ✓ tam odhaczy też tutaj.",
    vision_step_schedule_title: "📅 Zaplanuj w kalendarzu",
    vision_step_schedule_btn_title: "Zaplanuj w kalendarzu",
    nm_goal_reminder: "Pamiętaj o swoim celu",
    faq_a_share_whatsapp: "Opcję udostępniania znajdziesz w kilku miejscach: „Udostępnij to osiągnięcie” w oknie gratulacji po osiągnięciu celu, 📤 przy przepisie, 📤 obok treningu w sekcji Sport oraz „✨ Udostępnij Aplikację” w Ustawieniach. Wybierz WhatsApp, e-mail lub kopiowanie. Wiadomość wychodzi ładnie ułożona, ze szczegółami – przy celu: postęp, ile czasu to zajęło i Twoja nagroda; przy przepisie: składniki i kroki przygotowania; przy treningu: czas, dystans i zdjęcie. Na dole zawsze jest mały link do aplikacji, więc każdy, kto chce, może od razu do niej wejść. Przed wysłaniem nadal możesz edytować tekst w aplikacji WhatsApp.",
    faq_q_share_whatsapp: "Jak udostępnić cel, przepis lub trening przez WhatsApp?",
    sport_share_closing_3: "Dalej w ruchu",
    sport_share_closing_2: "Moje ciało mówi dziękuję",
    sport_share_closing_1: "Kolejny trening zaliczony",
    recipe_share_enjoy: "Smacznego!",
    goal_share_closing_3: "Wytrwałość popłaca",
    goal_share_closing_2: "Krok po kroku – i stało się",
    goal_share_closing_1: "Nie było łatwo – ale udało mi się",
    goal_share_reward_line: "Moja nagroda: {reward}",
    goal_share_days_taken: "Zajęło mi to {n} dni",
    goal_share_weight_up: "Plus {n} {unit}",
    goal_share_weight_down: "Minus {n} {unit}",
    goal_share_steps_line: "Kroki: {done}/{total}",
    goal_share_heading: "Cel osiągnięty!",
    share_footer_sent_from: "Wysłano z NOT10.ai",
    faq_a_goal_days_challenge: "W sekcji Moje Cele dotknij ＋ (lub gotowego przykładu „🔥 8 dni”), wybierz „📆 Wyzwanie codzienne”, wpisz liczbę dni i dodaj, co robisz każdego dnia (np. „30-minutowy spacer”, „Jeść według mojego menu”). Każdego dnia odhaczaj zadania z danego dnia pod ścieżką wyzwania – gdy wszystkie są odhaczone, dzień się liczy, ścieżka przesuwa się o jeden kamień i rośnie Twoja seria 🔥 (bez codziennych zadań jest jeden przycisk „✓ Dziś się udało”). Przycisk 🔁 obok zadania dodaje je do Mojej Rutyny o wybranej godzinie: odhaczenie tam odhacza je też w celu, i odwrotnie. Etapy zwykłego celu można dodać do Mojej Rutyny w ten sam sposób.",
