    vision_tagline: "Wielkie cele, małe kroki.",
    faq_a_app_tour: "Zwiedzanie otwiera się samo raz, przy pierwszym wejściu. Zaczyna się od swoich części – dotknij jednej, żeby od razu do niej przejść – a potem pokazuje wszystkie części aplikacji (ekran główny, asystenta AI i każdą pozycję menu) i pięć grup Ustawień, każdą z krótkim wyjaśnieniem, i zagląda do środka niektórych (na przykład przykładowa ścieżka celu, torba oraz Google Calendar). Dalej idzie naprzód, Wstecz cofa, Pomiń tę część przechodzi do następnej części, a ✕ zamyka zwiedzanie. Możesz je obejrzeć ponownie w każdej chwili w Ustawienia > Pomoc i użytkowanie > Zwiedzanie aplikacji i kontynuować od miejsca, w którym przerwano. Dalej i Wstecz są zawsze w tym samym miejscu na dole ekranu, a na komputerze działają też strzałki na klawiaturze.",
    faq_q_app_tour: "Jak ponownie obejrzeć zwiedzanie aplikacji?",
    apptour_done_text: "Masz pytanie? Sekcja Pomoc i FAQ w Ustawieniach odpowie na wszystko, a to zwiedzanie jest zawsze dostępne w sekcji Pomoc i użytkowanie.",
