    apptour_s_account_text: "Premium, hasło, osobisty raport PDF, synchronizacja z Google Calendar i usunięcie konta.",
    apptour_s_notifications_text: "Powiadomienia o przypomnieniach i ich dźwięk. Przycisk '⏰ Jeszcze nie' w przypomnieniu działa jak drzemka w budziku: przypomina ponownie co 5 minut.",
    apptour_s_personalization_text: "Kraj, liczba posiłków i przekąsek dziennie, początek miesiąca finansowego i to, co widać na ekranie głównym.",
