    apptour_ai_schedule_link: "Pojawią się w kalendarzu i w sekcji Mój Dzień.",
    apptour_ai_schedule_text: "Opisz plany zwykłymi słowami, jednorazowe lub cykliczne – trafią prosto do kalendarza.",
    apptour_ai_food_link: "Trafia prosto do sekcji Dzienny Rejestr Posiłków i do dzisiejszej sumy.",
    apptour_ai_food_text: "Wpisz, co było do jedzenia – kalorie zostaną oszacowane i zapisane za ciebie.",
    apptour_newme_short_text: "Otwiera New Me – dzisiejsze menu jest od razu na ekranie głównym.",
    apptour_ai_link: "Mała plakietka 1 na przycisku to codzienne przypomnienie „co jest dziś najważniejsze”.",
    apptour_ai_text: "Pisz prostymi słowami, a asystent zrobi resztę: zapisze kalorie, wpisze plany do kalendarza, odczyta przepis ze zdjęcia i zbuduje tabele.",
    apptour_quicknote_link: "📝 i 🛒 otwierają pełne listy; 🍎 dodaje zapisany posiłek do sekcji Dzienny Rejestr Posiłków.",
    apptour_quicknote_text: "Zanotuj coś szybko – do Notatek albo prosto na Listę Zakupów.",
    apptour_routine_link: "Nawyk może automatycznie zapisać trening w sekcji Śledzenie Treningów.",
    apptour_routine_text: "Twoja codzienna rutyna według godzin, w kartach (dzieci, nauka, praca…). Odhaczaj ✓ codziennie, by budować nawyki i serie; 📅 pokazuje cały miesiąc.",
    apptour_premium_text: "Odblokowuje pełnego asystenta AI, motywy, czcionki, Moją torbę i więcej.",
