    table_select_option_delete_confirm: "Ta opcja jest używana w wierszach: {count}. Usunąć ją? Te komórki zostaną wyczyszczone.",
    table_select_option_delete_title: "Usuń opcję",
    faq_a_other_manual_option: "Wszędzie tam, gdzie wybiera się z listy opcji, jest też '✏️ Inne' - wystarczy ją wybrać i wpisać dokładnie to, czego potrzeba. W tabeli z kolumną wyboru (np. 'Pokrewieństwo' w tabeli prezentów) dotknij komórki, wybierz '✏️ Inne', wpisz wartość (np. 'Siostrzeniec') i dotknij Dodaj - zostanie zapisana jako nowa opcja tej kolumny, więc następnym razem będzie już na liście. Mały × obok każdej opcji na tej liście usuwa opcję z kolumny. Przy wyborze ikony tabeli dostępnych jest wiele ikon (w tym kolorowe karteczki samoprzylepne). Tak samo działa to w kategoriach zapisanych posiłków, kategoriach przepisów, kategoriach wydatków cyklicznych (zapisywana jako nowa kategoria osobista) i kategoriach celów w sekcji Moje Cele.",
