    nm_drink_more: "+ Kolejny napój",
    nm_drink_add: "Dodaj",
    nm_drink_name_ph: "Napój (np. sok)",
    nm_drinks_hint: "Wystarczy wpisać nazwę napoju – kalorie są obliczane automatycznie, a liczbę można zmienić.",
    nm_slot_drinks: "Napoje",
    faq_a_new_me_tracking: "Dotknij następnej misji na górze New Me, a potem ✓ Zjedzone, żeby oznaczyć następny posiłek jako zjedzony – całe menu z ✓ przy każdym posiłku jest w Cały dzień, z boku, a dzisiejsze posiłki widać też w Moim Dniu na ekranie głównym – dotknięcie jednego z nich tam (lub najechanie na niego myszą) pokazuje dokładnie, co zjeść, z ✓ i Zamień. Wszystko synchronizuje się z Dziennym Rejestrem Posiłków: posiłki z planu, napoje i wszystko, co dodasz gdzie indziej (np. kawa z szybkiego dodawania), liczą się razem w New Me i w Moim Dniu – nic, co już wpisane, nie zostaje nadpisane, a usunięcie ✓ usuwa tylko część New Me. Gdy wszystkie dzisiejsze posiłki są zaznaczone, jest małe świętowanie. W „Napojach” zapisuje się napoje z całego dnia – razem do ~150 kcal, czyli około 3 napoje po maksymalnie ~50 kcal. Wystarczy wpisać nazwę napoju, a kalorie uzupełni automatycznie AI. Dwa wiersze kawa/herbata mają też pole „Mleko? Ile?” (np. „trochę” albo „50 ml”), a wyliczenie się aktualizuje; liczbę można zmienić przed dodaniem i także później. Napój z nazwą i kaloriami zapisuje się automatycznie, gdy tylko przejdziesz dalej – dotknięcie Dodaj jest opcjonalne. Dotknij ☆ obok napoju, żeby zapisać go jako stały – stałe napoje pojawiają się jako przyciski na górze karty Napoje, a jedno dotknięcie dodaje je do dnia. ⭐ zapisuje posiłek jako zapisany posiłek. „Tabela dzienna” pokazuje, co zjedzone, z kaloriami i białkiem. Mały 💎 obok trybu skupienia, u góry ekranu głównego, otwiera je bezpośrednio. Wartości kalorii i białka to szacunki AI i mogą zawierać błędy. Nie wszystko zjedzone? Pod zaznaczonym posiłkiem „Nie wszystko zjedzone?” odejmuje ćwierć, połowę albo trzy czwarte porcji – albo to, co wpiszesz, z wyliczeniem – a kalorie dnia się aktualizują.",
    faq_q_new_me_tracking: "Jak działają ✓, zamiany i kalorie w New Me?",
    faq_a_new_me_what: "New Me to osobny program dziennego menu z dwoma gotowymi planami – 1300 lub 1500 kalorii – złożonymi z 2 głównych posiłków i 2 przekąsek, z 3 opcjami dla każdego. Zawiera całe Premium. Cena: $11.99 miesięcznie (rezygnacja w każdej chwili) albo jednorazowo $99.99, na zawsze. Otwiera się go przez 💎 New Me w menu. Przed startem jest krótka ankieta, która zaczyna się od zastrzeżenia medycznego do zaakceptowania. Program to wyłącznie ogólna informacja i nie zastępuje lekarza ani dietetyka klinicznego.",
    faq_q_new_me_what: "Czym jest New Me i jak je uzyskać?",
