    nm_sales_f4: "Pełne menu w PDF w Twoim języku",
    nm_sales_f3: "Widok miesięczny ze śledzeniem wagi",
    nm_sales_f2: "Codzienny ✓ przy każdym posiłku oraz liczba kalorii pozostałych na dziś",
    nm_sales_f1: "Dwa gotowe plany (1300 / 1500 kcal) z co najmniej 3 opcjami na każdy posiłek",
    nm_sales_subtitle: "Gotowe menu dzienne na 1300 lub 1500 kalorii – ze śledzeniem, sprytnymi zamianami, wyzwaniami i drogą postępów.",
    faq_a_categories_menu: "Menu aplikacji może być wyświetlane na jeden z dwóch sposobów, a na górze widoczny jest tylko jeden przycisk: ☰ lista (domyślnie) lub ▦ duże kafelki - Planowanie i Kalendarz, Listy, Cele i Postępy, Odżywianie i Wskaźniki, Sport oraz Wydatki i Dochody; dotknij kafelka, aby zobaczyć jego zawartość, a potem dotknij tego, czego potrzebujesz. Aby przełączyć, otwórz menu i dotknij małego przycisku u jego góry: ▦ w menu listy przełącza na kafelki, a ☰ w menu kafelków wraca do listy. Menu kafelków ma też przycisk ⚙️ do Ustawień. Wybór jest zapisywany i obowiązuje na wszystkich urządzeniach.",
    faq_q_categories_menu: "Jak przełączać między menu listy ☰ a menu kafelków ▦?",
    new_me_coming_soon: "Nowy program osobisty jest w drodze - już wkrótce.",
    categories_menu_title: "Wszystkie kategorie",
    hamburger_group_planning: "Planowanie i Kalendarz",
    routine_overview_no_checks: "W tym miesiącu nie ma jeszcze odhaczeń - dotykaj ✓ obok elementów rutyny w dni, w które je wykonujesz.",
    faq_a_finance_cycle_day: "Domyślnie podsumowanie budżetu resetuje się 1. dnia każdego miesiąca kalendarzowego. Jeśli wypłata przychodzi innego dnia (np. 10.), ustaw tu ten dzień - wtedy miesięczne podsumowanie, historia i docelowy budżet będą liczone od tego dnia do tego samego dnia następnego miesiąca, a nie od 1. do końca miesiąca.",
    faq_q_finance_cycle_day: "Do czego służy ustawienie 'Dzień resetu miesięcznego budżetu'?",
    faq_a_quick_note_view_full_lists: "W menu ☰ od razu są Notatki i Lista Zakupów. W oknie Szybkiej Notatki (w Trybie skupienia) małe 📝 i 🛒 obok Dodaj też tam prowadzą, a 🍎 szybko dodaje jeden z zapisanych posiłków.",
