    note_triage_otherdate: "Inna Data", note_triage_otherdate_modal_title: "Wybierz datę", note_triage_otherdate_missing: "Proszę wybrać datę", note_triage_success_otherdate: "Dodano do harmonogramu!", notes_ai_placeholder_shopping: "Dodaj do listy",
    daily_greeting_morning: "Dzień dobry!", daily_greeting_afternoon: "Miłego popołudnia!", daily_greeting_evening: "Dobry wieczór!", daily_greeting_night: "Dobranoc!", calorie_monthly_view_title: "Widok Miesięczny", calorie_monthly_avg_label: "Średnia dzienna:", calorie_monthly_avg_empty: "Brak jeszcze danych w tym miesiącu", calorie_monthly_day_total_label: "Suma dnia:", notes_ai_added_shopping: "Dodano do Twojej listy zakupów", quick_note_dest_notes: "📝 Notatki", quick_note_dest_shopping: "🛒 Lista Zakupów",
    faq_q_calorie_monthly_view: "Jak zobaczyć historię kalorii z całego miesiąca?", faq_a_calorie_monthly_view: "Wskaźniki Kalorii i Wagi mają kartę 'Widok Miesięczny' z kalendarzem - każdy dzień, w którym zapisałeś posiłki, oznaczony jest kropką, a średnia dzienna z danego miesiąca widoczna jest nad siatką. Dotknij dowolnego dnia, aby zobaczyć dokładnie, co zjadłeś i jaka była suma. Ten sam podział jest też uwzględniony podczas pobierania Raportu Osobistego (PDF) z Ustawień, jeśli zaznaczona jest sekcja Wskaźniki Kalorii i Wagi.",
    faq_q_calorie_stats_total_vs_average: "Czy liczby Tygodniowo/Miesięcznie we Wskaźnikach Kalorii to suma czy średnia?", faq_a_calorie_stats_total_vs_average: "To jedno i drugie - duża liczba to suma (łączna) wszystkiego zapisanego w bieżącym tygodniu/miesiącu kalendarzowym, a mała linijka pod nią to średnia dzienna. Średnia jest dzielona tylko przez dni, w których faktycznie coś zapisałeś, a nie przez 7 czy cały miesiąc - dzień bez żadnego wpisu jest po prostu pomijany, nie liczy się jako 0 i nie obniża średniej.",
    faq_q_weight_note: "Czy mogę dodać notatkę do wpisu wagi?", faq_a_weight_note: "Tak - obok pól wagi/daty w Okresowym Śledzeniu Wagi (znajdziesz je na dole sekcji Odżywianie i Wskaźniki > Wskaźniki Kalorii i Wagi, pod ⚖️) znajduje się opcjonalne pole notatki. Możesz go użyć, żeby dodać kontekst, na przykład \"po treningu\" albo \"poranne ważenie\" - notatka pojawi się obok tego wpisu na liście historii.",
    faq_q_quick_note_shopping_list: "Czy Szybka Notatka może dodawać prosto do listy zakupów?", faq_a_quick_note_shopping_list: "Tak – w linii do pisania na środku ekranu głównego dotknij 📝 na jej początku: zmieni się w 🛒, a to, co napiszesz, trafi prosto na Listę Zakupów, z pominięciem Notatek.",
