    calorie_stat_avg_label: "Śr.: {amount}",
    daily_focus_modal_title: "🧠 Co jest dla Ciebie dziś najważniejsze do zrobienia?", daily_focus_modal_subtitle: "Odpowiedz, a to trafi prosto do dzisiejszego planu.", daily_focus_input_placeholder: "Dziś najbardziej chcę", daily_focus_save_btn: "Dodaj do dzisiejszego planu", daily_focus_skip_btn: "Nie teraz", daily_focus_missing_text: "Najpierw coś napisz", daily_focus_added_toast: "Dodano do dzisiejszego planu", daily_focus_other_option: "✍️ Inne...",
    daily_focus_c1_d0: "Chronić swoją ciszę przed zgiełkiem dookoła", daily_focus_c1_d1: "Wyznaczać jasne granice - z miłością i bez poczucia winy", daily_focus_c1_d2: "Trzymać się swojego oparcia, nawet gdy dookoła szaleje burza", daily_focus_c1_d3: "Stawiać swój spokój i energię na pierwszym miejscu", daily_focus_c1_d4: "Nie brać na siebie emocji i nastrojów innych ludzi", daily_focus_c1_d5: "Nie pozwalać, by słowa innych podważały moją wartość",
    daily_focus_c2_d0: "Słuchać tego, czego potrzebuje moje ciało i umysł", daily_focus_c2_d1: "Cieszyć się małymi rzeczami po drodze", daily_focus_c2_d2: "Zwolnić tempo i naprawdę wsłuchać się w siebie", daily_focus_c2_d3: "Dawać sobie przestrzeń na oddech w środku zabiegania", daily_focus_c2_d4: "Czuć się bezpiecznie i spokojnie we własnym wnętrzu", daily_focus_c2_d5: "Skupiać się na tym, co dzieje się teraz, bez wybiegania naprzód",
    daily_focus_c3_d0: "Dbać o to, by moje słowa były pełne wsparcia, cierpliwości i zrozumienia", daily_focus_c3_d1: "Nie brać niczego do siebie", daily_focus_c3_d2: "Nie zakładać - po prostu zapytać albo odpuścić", daily_focus_c3_d3: "Ufać własnemu tempu i własnej drodze", daily_focus_c3_d4: "Odpuścić perfekcję i wybrać postęp", daily_focus_c3_d5: "Zachować cierpliwość wobec własnego procesu",
    daily_focus_c4_d0: "Kończyć dzień z poczuciem dumy i spełnienia", daily_focus_c4_d1: "Zauważać swój postęp, nawet w małych krokach", daily_focus_c4_d2: "Skupiać się na jednym zadaniu na raz", daily_focus_c4_d3: "Wprowadzać porządek w swoich zadaniach i działać spokojnie", daily_focus_c4_d4: "Akceptować siebie dokładnie taką, jaka jestem dzisiaj", daily_focus_c4_d5: "Wiedzieć, kiedy działać, a kiedy odpuścić",
    daily_focus_c5_d0: "Wnosić uśmiech i lekkość we wszystko, co robię", daily_focus_c5_d1: "Zaczynać dzień ze świeżą, dobrą energią", daily_focus_c5_d2: "Podarować sobie jeden spokojny dzień bez nadmiernych oczekiwań", daily_focus_c5_d3: "Wprowadzać odrobinę prostej radości do swojej codzienności", daily_focus_c5_d4: "Otwierać dziś serce na miłe niespodzianki", daily_focus_c5_d5: "Zaczynać dzień z wdzięcznością i uśmiechem",
